CREATE TABLE IF NOT EXISTS plantillas_mensaje (
    id SERIAL PRIMARY KEY,
    clave VARCHAR(80) NOT NULL UNIQUE,
    nombre VARCHAR(180) NOT NULL,
    asunto_email TEXT,
    cuerpo_email TEXT NOT NULL,
    cuerpo_whatsapp TEXT NOT NULL,
    variables_ejemplo JSON NOT NULL DEFAULT '{}'::json,
    enlace_ejemplo VARCHAR(1000),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    actualizado_por_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);
-- También corrige tablas creadas previamente por SQLAlchemy, donde los
-- valores por defecto pueden no haberse creado en la base de datos.
ALTER TABLE plantillas_mensaje ALTER COLUMN activo SET DEFAULT TRUE;
ALTER TABLE plantillas_mensaje ALTER COLUMN updated_at SET DEFAULT NOW();

INSERT INTO plantillas_mensaje (clave, nombre, asunto_email, cuerpo_email, cuerpo_whatsapp, variables_ejemplo, enlace_ejemplo, titulo_push, cuerpo_push) VALUES
('ACTUACION_NOTIFICADA', 'Actuación judicial informada', 'Novedad del juzgado en su proceso {{proceso}}', '# Hay una novedad del juzgado en su proceso\nHola, {{primer_nombre}}:\n{{actor}} le informa una actuación nueva en su proceso {{proceso}}.\n> {{comentarios}}\nSi esta novedad requiere algo de usted, se lo indicaremos.\nAbrir enlace: Ver la actuación | {{enlace}}\nProceso: {{proceso}}\nRadicado: {{radicado}}\nActuación: {{actuacion}}\nNota del juzgado: {{anotacion}}\nFecha: {{fecha}}\n? Si tiene dudas, escríbanos por el chat del portal.', 'Hola, {{primer_nombre}}.\nHay una novedad del juzgado en su proceso *{{proceso}}*.\n{{comentarios}}\nActuación: {{actuacion}}\nFecha: {{fecha}}\nSi esta novedad requiere algo de usted, se lo indicaremos.\nAbrir enlace: Ver la actuación | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "proceso": "Sucesión de Jorge Pérez", "radicado": "05001311001220250035600", "fecha": "2026-10-15", "actuacion": "Auto admite demanda", "anotacion": "Se admite la demanda y se ordena notificar.", "comentarios": "El juzgado aceptó estudiar la demanda. Es un paso normal del proceso."}', 'https://panel.alejandramunozabogada.com/procesos/1#actuacion-1', NULL, NULL),
('ACTUACIONES_DIGEST', 'Novedades judiciales', 'Novedades del juzgado en sus procesos', '# Hay novedades del juzgado\nHola, {{primer_nombre}}:\nLa Rama Judicial registró actuaciones nuevas en estos procesos.\n\n{{novedades}}\n\n? Si tiene dudas, escríbanos por el chat del portal.', 'Hola, {{primer_nombre}}.\nHay novedades del juzgado en sus procesos:\n\n{{novedades}}', '{"nombre": "María Pérez", "novedades": "Proceso: Sucesión de Jorge Pérez\nRadicado: 05001 31 10 012 2025 00356 00\nActuación: Auto admite demanda\nFecha: miércoles 15 de octubre de 2026\nAbrir enlace: Ver las novedades de Sucesión de Jorge Pérez | https://panel.alejandramunozabogada.com/procesos/1#radicado-1", "proceso": "Sucesión de Jorge Pérez", "radicado": "05001311001220250035600", "fecha": "2026-10-15", "actuacion": "Auto admite demanda", "anotacion": "Se admite la demanda."}', NULL, 'Novedad del juzgado: {{proceso}}', '{{actuacion}}\n{{fecha}}'),
('CLIENTE_CREDENCIALES', 'Credenciales de cliente', 'Su acceso al portal del despacho', '# Ya puede consultar sus procesos en línea\nHola, {{primer_nombre}}:\n{{actor}} creó su acceso al portal del despacho. Allí verá cómo va su proceso, los documentos que le pedimos y los mensajes de su abogado.\nUsuario: {{correo}}\nContraseña temporal: {{password}}\n! Entre al portal con estos datos. La primera vez, el portal le pedirá crear una contraseña nueva.\nAbrir enlace: Entrar al portal | {{enlace}}\nLe avisaremos de las novedades por {{canal}}.\n? No comparta su contraseña con nadie. El despacho nunca se la pedirá por teléfono, correo ni WhatsApp.', 'Hola, {{primer_nombre}}.\n{{actor}} creó su acceso al portal del despacho, donde puede ver cómo va su proceso.\nLe enviamos el usuario y la contraseña temporal a su correo *{{correo}}*.\nSi no lo encuentra, revise la carpeta de correo no deseado.\nAbrir enlace: Entrar al portal | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "correo": "cliente@example.com", "password": "Temporal123", "canal": "WHATSAPP"}', 'https://panel.alejandramunozabogada.com/', NULL, NULL),
('ABOGADO_CREDENCIALES', 'Acceso de abogado', 'Su acceso al portal del despacho', '# Su acceso al portal está listo\nHola, {{primer_nombre}}:\nSe creó su cuenta de abogado en el portal de gestión de procesos.\nUsuario: {{correo}}\n! Entre con la contraseña temporal que le entregaron. La primera vez, el portal le pedirá cambiarla.\nAbrir enlace: Entrar al portal | {{enlace}}\n? No comparta su contraseña con nadie.', 'Hola, {{primer_nombre}}.\nSe creó su cuenta de abogado en el portal del despacho.\nUsuario: {{correo}}\nEntre con la contraseña temporal que le entregaron y cámbiela al ingresar.\nAbrir enlace: Entrar al portal | {{enlace}}', '{"nombre": "Carolina Ríos", "correo": "abogada@example.com"}', 'https://panel.alejandramunozabogada.com/', NULL, NULL),
('CODIGO_SEGURIDAD', 'Código de seguridad OTP', 'Su código de seguridad', '# Su código de seguridad\nHola, {{primer_nombre}}:\nUse este código para confirmar el cambio en su cuenta.\nCódigo: {{codigo}}\n! Escríbalo en el portal antes de 3 minutos.\n? No comparta este código con nadie, ni siquiera con el despacho. Si usted no pidió este cambio, ignore este mensaje y su cuenta seguirá igual.', 'Hola, {{primer_nombre}}.\nSu código de seguridad es *{{codigo}}*.\nVence en 3 minutos. No lo comparta con nadie, ni siquiera con el despacho.\nSi usted no pidió este cambio, ignore este mensaje.', '{"nombre": "María Pérez", "codigo": "123456"}', NULL, NULL, NULL),
('CAMBIO_SEGURIDAD_CONFIRMADO', 'Confirmación de cambio de seguridad', 'Se cambió el {{cambio}} de su cuenta', '# Se hizo un cambio en su cuenta\nHola, {{primer_nombre}}:\nSe actualizó el {{cambio}} de acceso a su cuenta del portal.\nSi usted hizo este cambio, no tiene que hacer nada.\n! Si usted no lo hizo, comuníquese de inmediato con el despacho para proteger su cuenta.', 'Hola, {{primer_nombre}}.\nSe actualizó el *{{cambio}}* de acceso a su cuenta del portal.\nSi usted hizo este cambio, no tiene que hacer nada.\nSi no lo hizo, comuníquese de inmediato con el despacho.', '{"nombre": "María Pérez", "cambio": "correo de acceso"}', NULL, NULL, NULL),
('CHAT_MENSAJE', 'Aviso de nuevos mensajes de chat', '{{actor}} le escribió por el chat', '# Tiene mensajes nuevos\nHola, {{primer_nombre}}:\n{{actor}} le está escribiendo por el chat del portal.\nAbrir enlace: Leer los mensajes | {{enlace}}', 'Hola, {{primer_nombre}}.\n*{{actor}}* le está escribiendo por el chat del portal.\nAbrir enlace: Leer los mensajes | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz"}', 'https://panel.alejandramunozabogada.com/chat/1/2', NULL, NULL),
('COLABORADOR_AGREGADO', 'Abogado agregado al proceso', 'Ahora participa en el proceso {{proceso}}', '# Ahora participa en un proceso\nHola, {{primer_nombre}}:\n{{actor}} le dio acceso al proceso {{proceso}}.\nProceso: {{proceso}}\nResponsable: {{responsable}}\nSu participación: {{permiso}}\nAbrir enlace: Ver el proceso | {{enlace}}', 'Hola, {{primer_nombre}}.\n{{actor}} le dio acceso al proceso *{{proceso}}*.\nResponsable: {{responsable}}\nSu participación: {{permiso}}\nAbrir enlace: Ver el proceso | {{enlace}}', '{"nombre": "Carolina Ríos", "actor": "Alejandra Muñoz", "permiso": "colaborador interno", "proceso": "Sucesión de Jorge Pérez", "responsable": "Alejandra Muñoz"}', 'https://panel.alejandramunozabogada.com/procesos/1/resumen', NULL, NULL),
('COMUNICACION_ABOGADO_CLIENTE', 'Comunicación del despacho al cliente', 'Mensaje del despacho: {{asunto}}', '# Tiene un mensaje del despacho\nHola, {{primer_nombre}}:\n{{actor}} le escribió sobre su proceso {{proceso}}.\nAsunto: {{asunto}}\nFecha: {{fecha}}\n\nMensaje:\n{{mensaje}}\n\nAbrir enlace: Leer y responder | {{enlace}}', 'Hola, {{primer_nombre}}.\n*{{actor}}* le escribió sobre su proceso *{{proceso}}*.\nAsunto: {{asunto}}\n{{mensaje}}\nAbrir enlace: Leer y responder | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "proceso": "Sucesión de Jorge Pérez", "asunto": "Fecha de la audiencia", "fecha": "15/10/2026 09:00", "mensaje": "La audiencia quedó para el martes 3 de noviembre. Le confirmo la hora mañana."}', 'https://panel.alejandramunozabogada.com/chat/1/2', NULL, NULL),
('COMUNICACION_CLIENTE_ABOGADO', 'Mensaje de cliente al despacho', 'Mensaje de {{actor}}: {{asunto}}', '# Un cliente le escribió\nHola, {{primer_nombre}}:\n{{actor}} le escribió sobre el proceso {{proceso}}.\nAsunto: {{asunto}}\nFecha: {{fecha}}\n\nMensaje:\n{{mensaje}}\n\nAbrir enlace: Leer y responder | {{enlace}}', 'Hola, {{primer_nombre}}.\n*{{actor}}* le escribió sobre el proceso *{{proceso}}*.\nAsunto: {{asunto}}\n{{mensaje}}\nAbrir enlace: Leer y responder | {{enlace}}', '{"nombre": "Alejandra Muñoz", "actor": "María Pérez", "proceso": "Sucesión de Jorge Pérez", "asunto": "Consulta", "fecha": "15/10/2026 09:00", "mensaje": "¿Necesitan algo más de mi parte?"}', 'https://panel.alejandramunozabogada.com/chat/1/2', NULL, NULL),
('CONTRATO_FIRMADO', 'Copia de contrato firmado', 'Copia de su contrato firmado', '# Le enviamos su contrato firmado\nHola, {{primer_nombre}}:\nAdjuntamos la copia escaneada del contrato de prestación de servicios que firmó para el proceso {{proceso}}.\nGuárdela en un lugar seguro. También la puede consultar en cualquier momento en el portal.\nAbrir enlace: Ver mis documentos | {{enlace}}\n? Si tiene preguntas sobre el contrato, escríbanos por el chat del portal.', 'Hola, {{primer_nombre}}.\nLe enviamos a su correo la copia del contrato firmado para *{{proceso}}*.\nTambién la puede ver en el portal.\nAbrir enlace: Ver mis documentos | {{enlace}}', '{"nombre": "María Pérez", "proceso": "Sucesión de Jorge Pérez"}', 'https://panel.alejandramunozabogada.com/procesos/1#documentos', NULL, NULL),
('DOCUMENTO_RECIBIDO', 'Documento recibido', '{{actor}} entregó un documento: {{documento}}', '# Llegó un documento para revisar\nHola, {{primer_nombre}}:\n{{actor}} subió un archivo para la solicitud {{solicitud}} del proceso {{proceso}}.\nDocumento pedido: {{documento}}\nArchivo recibido: {{archivo}}\nFecha: {{fecha}}\n! Revíselo y apruébelo o pida una corrección.\nAbrir enlace: Revisar el documento | {{enlace}}', 'Hola, {{primer_nombre}}.\n*{{actor}}* entregó *{{documento}}* para el proceso *{{proceso}}*.\nRevíselo y apruébelo o pida una corrección.\nAbrir enlace: Revisar el documento | {{enlace}}', '{"nombre": "Alejandra Muñoz", "actor": "María Pérez", "proceso": "Sucesión de Jorge Pérez", "solicitud": "Documentos para la demanda", "documento": "Copia de la cédula", "archivo": "cedula_frente.pdf", "tipo": "application/pdf", "fecha": "15/10/2026 09:00"}', 'https://panel.alejandramunozabogada.com/procesos/1/documentos', NULL, NULL),
('DOCUMENTO_REVISION', 'Revisión de documento', 'Revisamos su documento: {{documento}}', '# Revisamos su documento\nHola, {{primer_nombre}}:\n{{actor}} revisó el documento que usted entregó para el proceso {{proceso}}.\nDocumento: {{documento}}\nResultado: {{estado}}\nComentario del abogado: {{comentario}}\nArchivo: {{archivo}}\nFecha: {{fecha}}\nSi el resultado es «necesita corrección», lea el comentario y suba el documento de nuevo. Si es «aprobado», no tiene que hacer nada más.\nAbrir enlace: Ver mis documentos | {{enlace}}', 'Hola, {{primer_nombre}}.\nRevisamos su documento *{{documento}}*.\nResultado: *{{estado}}*\nComentario: {{comentario}}\nSi necesita corrección, súbalo de nuevo desde el portal.\nAbrir enlace: Ver mis documentos | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "proceso": "Sucesión de Jorge Pérez", "solicitud": "Documentos para la demanda", "documento": "Copia de la cédula", "archivo": "cedula_frente.pdf", "estado": "REQUIERE_CORRECCION", "comentario": "La foto quedó borrosa. Tómela de nuevo con buena luz.", "fecha": "15/10/2026 09:00"}', 'https://panel.alejandramunozabogada.com/procesos/1#documentos', NULL, NULL),
('EVENTO_AGENDA', 'Actividad de agenda', 'Actividad de su proceso: {{actividad}}', '# {{actividad}}\nHola, {{primer_nombre}}:\n{{actor}} {{accion}} una actividad de su proceso {{proceso}}.\nCuándo: {{inicio}}\nHasta: {{fin}}\nQué es: {{tipo}}\nEstado: {{estado}}\nResponsable: {{responsable}}\nDetalle: {{detalle}}\nAbrir enlace: Ver la actividad | {{enlace}}\n? Si no puede asistir o tiene dudas, escríbanos por el chat del portal.', 'Hola, {{primer_nombre}}.\n{{actor}} {{accion}} una actividad de su proceso *{{proceso}}*:\n*{{actividad}}*\nCuándo: {{inicio}}\nEstado: {{estado}}\nDetalle: {{detalle}}\nAbrir enlace: Ver la actividad | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "accion": "programó", "proceso": "Sucesión de Jorge Pérez", "actividad": "Audiencia inicial", "tipo": "AUDIENCIA", "estado": "PROGRAMADO", "inicio": "03/11/2026 09:00", "fin": "No indicada", "responsable": "Alejandra Muñoz", "detalle": "Audiencia virtual. Le enviaremos el enlace un día antes."}', 'https://panel.alejandramunozabogada.com/procesos/1#evento-1', NULL, NULL),
('PROCESO_ACTUALIZACION', 'Actualización de proceso', 'Actualización de su proceso {{proceso}}', '# Hay una actualización en su proceso\nHola, {{primer_nombre}}:\n{{actor}} {{accion}}.\nProceso: {{proceso}}\nFecha: {{fecha}}\n\n{{detalle}}\n\nNo tiene que hacer nada por ahora.\nAbrir enlace: Ver mi proceso | {{enlace}}', 'Hola, {{primer_nombre}}.\n{{actor}} {{accion}}.\nProceso: {{proceso}}\nNo tiene que hacer nada por ahora.\nAbrir enlace: Ver mi proceso | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "accion": "asoció un radicado judicial al proceso", "proceso": "Sucesión de Jorge Pérez", "fecha": "15/10/2026 09:00", "detalle": "Radicado: 05001 31 10 012 2025 00356 00"}', 'https://panel.alejandramunozabogada.com/procesos/1', NULL, NULL),
('PRUEBA_INTEGRACION', 'Prueba de integración', 'Prueba de envío del portal', '# Prueba de envío\nEste es un mensaje de prueba solicitado desde administración.\nSi lo recibió, este canal funciona bien. No tiene que hacer nada.', 'Hola.\nEste es un mensaje de prueba solicitado desde administración.\nSi lo recibió, este canal funciona bien.', '{}', NULL, NULL, NULL),
('REACTIVACION_COMUNICACION', 'Comunicación pendiente al reactivar usuario', 'Tiene un mensaje pendiente: {{asunto}}', '# Tiene un mensaje pendiente\nHola, {{primer_nombre}}:\nSu cuenta está activa de nuevo. Mientras estuvo inactiva le escribieron sobre el proceso {{proceso}}.\nAsunto: {{asunto}}\nFecha: {{fecha}}\n\nMensaje:\n{{mensaje}}\n\nAbrir enlace: Leer el mensaje | {{enlace}}', 'Hola, {{primer_nombre}}.\nSu cuenta está activa de nuevo y tiene un mensaje pendiente sobre *{{proceso}}*.\nAsunto: {{asunto}}\nAbrir enlace: Leer el mensaje | {{enlace}}', '{"nombre": "María Pérez", "proceso": "Sucesión de Jorge Pérez", "asunto": "Documentos pendientes", "fecha": "15/10/2026 09:00", "mensaje": "Le recordamos enviar el registro civil."}', 'https://panel.alejandramunozabogada.com/chat/1/2', NULL, NULL),
('REACTIVACION_EVENTO', 'Actividad próxima al reactivar usuario', 'Tiene una actividad próxima: {{actividad}}', '# Tiene una actividad próxima\nHola, {{primer_nombre}}:\nSu cuenta está activa de nuevo. Le recordamos esta actividad de su proceso {{proceso}}.\nActividad: {{actividad}}\nCuándo: {{fecha}}\nQué es: {{tipo}}\nDetalle: {{descripcion}}\nAbrir enlace: Ver la actividad | {{enlace}}', 'Hola, {{primer_nombre}}.\nSu cuenta está activa de nuevo. Le recordamos *{{actividad}}* de su proceso *{{proceso}}*.\nCuándo: {{fecha}}\nAbrir enlace: Ver la actividad | {{enlace}}', '{"nombre": "María Pérez", "actividad": "Audiencia inicial", "proceso": "Sucesión de Jorge Pérez", "tipo": "AUDIENCIA", "fecha": "03/11/2026 09:00", "descripcion": "Sin detalles adicionales"}', 'https://panel.alejandramunozabogada.com/procesos/1#evento-1', NULL, NULL),
('REACTIVACION_TAREA', 'Tarea pendiente al reactivar usuario', 'Tiene una tarea pendiente: {{tarea}}', '# Tiene una tarea pendiente\nHola, {{primer_nombre}}:\nSu cuenta está activa de nuevo y tiene esta tarea por hacer.\nTarea: {{tarea}}\nFecha límite: {{fecha_limite}}\nProceso: {{proceso}}\nEstado: {{estado}}\n! Revise la tarea y márquela como completada cuando termine.\nAbrir enlace: Ver la tarea | {{enlace}}', 'Hola, {{primer_nombre}}.\nSu cuenta está activa de nuevo y tiene una tarea pendiente: *{{tarea}}*.\nFecha límite: {{fecha_limite}}\nAbrir enlace: Ver la tarea | {{enlace}}', '{"nombre": "María Pérez", "tarea": "Firmar el poder", "proceso": "Sucesión de Jorge Pérez", "estado": "PENDIENTE", "fecha_limite": "20/11/2026 23:59"}', 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1', NULL, NULL),
('RECORDATORIO_DOCUMENTO', 'Recordatorio de documentos pendientes', 'Recordatorio: todavía nos faltan documentos', '# Todavía nos faltan documentos\nHola, {{primer_nombre}}:\nLe recordamos que la solicitud {{solicitud}} de su proceso {{proceso}} {{cuando}}.\nDocumentos que faltan:\n{{pendientes}}\n! Súbalos desde el portal en PDF o como foto legible.\nAbrir enlace: Subir los documentos | {{enlace}}\n? Si no sabe cómo conseguir alguno, escríbanos por el chat del portal y le ayudamos.', 'Hola, {{primer_nombre}}.\nLe recordamos que la solicitud *{{solicitud}}* {{cuando}}.\nFaltan estos documentos:\n{{pendientes}}\nProceso: {{proceso}}\nAbrir enlace: Subir los documentos | {{enlace}}', '{"nombre": "María Pérez", "proceso": "Sucesión de Jorge Pérez", "solicitud": "Documentos para la demanda", "cuando": "vence mañana, 30 de octubre", "pendientes": "- Copia de la cédula\n- Registro civil", "fecha_limite": "30/10/2026"}', 'https://panel.alejandramunozabogada.com/procesos/1#documentos', 'Recordatorio: faltan documentos', 'La solicitud {{solicitud}} {{cuando}}. Falta:\n{{pendientes}}'),
('RECORDATORIO_TAREA', 'Recordatorio de tarea', 'Recordatorio: {{tarea}}', '# Recordatorio de una tarea\nHola, {{primer_nombre}}:\nLe recordamos esta tarea.\nTarea: {{tarea}}\nFecha límite: {{fecha_limite}}\nPrioridad: {{prioridad}}\nProceso: {{proceso}}\nRadicado: {{radicado}}\nActuación: {{actuacion}}\nDetalle: {{detalle}}\n! Revise la tarea y márquela como completada cuando termine.\nAbrir enlace: Ver la tarea | {{enlace}}', 'Hola, {{primer_nombre}}.\nLe recordamos la tarea *{{tarea}}*.\nFecha límite: {{fecha_limite}}\nProceso: {{proceso}}\nDetalle: {{detalle}}\nAbrir enlace: Ver la tarea | {{enlace}}', '{"nombre": "María Pérez", "tarea": "Preparar documentos", "estado": "PENDIENTE", "prioridad": "ALTA", "proceso": "Sucesión de Jorge Pérez", "radicado": "No asociado", "actuacion": "No asociada", "detalle": "Revisar los soportes de pago", "fecha_limite": "20/11/2026 17:00", "anticipacion": "24 horas antes"}', 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1', NULL, NULL),
('RECUPERAR_PASSWORD', 'Recuperación de contraseña', 'Cree una contraseña nueva', '# Cree una contraseña nueva\nHola:\nRecibimos una solicitud para cambiar la contraseña de su cuenta en el portal.\n! Use el botón para crear una contraseña nueva. El enlace sirve por 20 minutos y una sola vez.\nAbrir enlace: Crear contraseña nueva | {{enlace}}\n? Si usted no pidió este cambio, ignore este correo. Su contraseña actual sigue funcionando.', 'Hola.\nRecibimos una solicitud para cambiar su contraseña. El enlace sirve por 20 minutos.\nSi usted no la pidió, ignore este mensaje.\nAbrir enlace: Crear contraseña nueva | {{enlace}}', '{}', 'https://panel.alejandramunozabogada.com/restablecer-password?token=ejemplo', NULL, NULL),
('RESUMEN_MENSUAL', 'Resumen mensual de procesos', 'Resumen de sus procesos de {{mes}}', '# Resumen de sus procesos de {{mes}}\nHola, {{primer_nombre}}:\nEste es el estado de sus procesos activos.\n\n{{resumen}}\n\n? Si tiene dudas, escríbanos por el chat del portal.', 'Hola, {{primer_nombre}}.\nEste es el resumen de sus procesos de *{{mes}}*:\n\n{{resumen}}', '{"nombre": "Alejandra Muñoz", "mes": "octubre de 2026", "resumen": "Radicado: 05001 31 10 012 2025 00356 00\nJuzgado: Juzgado 12 de Familia de Medellín\nÚltima actuación: Auto admite demanda\nFecha: miércoles 15 de octubre de 2026"}', NULL, NULL, NULL),
('SOLICITUD_DOCUMENTO', 'Solicitud de documento', 'Necesitamos documentos para su proceso', '# Necesitamos documentos suyos\nHola, {{primer_nombre}}:\n{{actor}} necesita estos documentos para continuar con su proceso {{proceso}}:\n{{documentos}}\nEntregar antes del: {{fecha_limite}}\nIndicaciones: {{instrucciones}}\n! Súbalos desde el portal en PDF o como foto legible.\nAbrir enlace: Subir los documentos | {{enlace}}\n? Si no sabe cómo conseguir alguno, escríbanos por el chat del portal y le ayudamos.', 'Hola, {{primer_nombre}}.\nNecesitamos estos documentos para su proceso *{{proceso}}*:\n{{documentos}}\nEntregar antes del: {{fecha_limite}}\nIndicaciones: {{instrucciones}}\nSúbalos en PDF o como foto legible.\nAbrir enlace: Subir los documentos | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "proceso": "Sucesión de Jorge Pérez", "solicitud": "Documentos para la demanda", "documentos": "- Copia de la cédula\n- Registro civil", "instrucciones": "Ambas caras de la cédula, en una sola hoja.", "fecha_limite": "20/11/2026", "fecha": "15/11/2026 09:00"}', 'https://panel.alejandramunozabogada.com/procesos/1#documentos', NULL, NULL),
('SUBTAREA_ASIGNADA', 'Subtarea asignada', 'Tiene una tarea nueva: {{subtarea}}', '# Tiene una tarea nueva\nHola, {{primer_nombre}}:\n{{actor}} le asignó una tarea en el portal.\nTarea: {{subtarea}}\nHace parte de: {{tarea}}\n! Ábrala para ver qué debe hacer y márquela como completada cuando termine.\nAbrir enlace: Ver la tarea | {{enlace}}', 'Hola, {{primer_nombre}}.\n{{actor}} le asignó una tarea: *{{subtarea}}*.\nÁbrala para ver qué debe hacer.\nAbrir enlace: Ver la tarea | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "subtarea": "Firmar el poder", "tarea": "Preparar la demanda"}', 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1', NULL, NULL),
('TAREA_ACCION', 'Cambios de tareas', '{{actor}} {{accion}}: {{tarea}}', '# Cambio en una tarea\nHola, {{primer_nombre}}:\n{{actor}} {{accion}}.\nTarea: {{tarea}}\nQué cambió: {{detalle}}\nEstado: {{estado}}\nFecha límite: {{fecha_limite}}\nPrioridad: {{prioridad}}\nProceso: {{proceso}}\nRadicado: {{radicado}}\nActuación: {{actuacion}}\nAbrir enlace: Ver mis tareas | {{enlace}}', 'Hola, {{primer_nombre}}.\n{{actor}} {{accion}}: *{{tarea}}*.\nQué cambió: {{detalle}}\nEstado: {{estado}}\nFecha límite: {{fecha_limite}}\nAbrir enlace: Ver mis tareas | {{enlace}}', '{"nombre": "María Pérez", "actor": "Alejandra Muñoz", "accion": "cambió la fecha límite", "tarea": "Firmar el poder", "detalle": "La nueva fecha es el viernes 20 de noviembre.", "estado": "PENDIENTE", "prioridad": "ALTA", "fecha_limite": "20/11/2026 17:00", "proceso": "Sucesión de Jorge Pérez", "radicado": "05001311001220250035600", "actuacion": "No asociada"}', 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1', NULL, NULL)
ON CONFLICT (clave) DO UPDATE SET variables_ejemplo = replace(replace(plantillas_mensaje.variables_ejemplo::text, '09:00 UTC', '04:00'), ' UTC', '')::json WHERE plantillas_mensaje.variables_ejemplo::text LIKE '% UTC%';


UPDATE plantillas_mensaje
SET enlace_ejemplo = CASE clave
    WHEN 'EVENTO_AGENDA' THEN 'https://panel.alejandramunozabogada.com/procesos/1#evento-1'
    WHEN 'PROCESO_ACTUALIZACION' THEN 'https://panel.alejandramunozabogada.com/procesos/1'
    WHEN 'ABOGADO_CREDENCIALES' THEN 'https://panel.alejandramunozabogada.com/'
    WHEN 'CLIENTE_CREDENCIALES' THEN 'https://panel.alejandramunozabogada.com/'
    WHEN 'DOCUMENTO_REVISION' THEN 'https://panel.alejandramunozabogada.com/procesos/1#documentos'
    WHEN 'COMUNICACION_CLIENTE_ABOGADO' THEN 'https://panel.alejandramunozabogada.com/chat/1/2'
    WHEN 'COMUNICACION_ABOGADO_CLIENTE' THEN 'https://panel.alejandramunozabogada.com/chat/1/2'
    WHEN 'COLABORADOR_AGREGADO' THEN 'https://panel.alejandramunozabogada.com/procesos/1/resumen'
    WHEN 'ACTUACION_NOTIFICADA' THEN 'https://panel.alejandramunozabogada.com/procesos/1#actuacion-1'
    WHEN 'SOLICITUD_DOCUMENTO' THEN 'https://panel.alejandramunozabogada.com/procesos/1#documentos'
    WHEN 'DOCUMENTO_RECIBIDO' THEN 'https://panel.alejandramunozabogada.com/procesos/1/documentos'
    WHEN 'TAREA_ACCION' THEN 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1'
    WHEN 'SUBTAREA_ASIGNADA' THEN 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1'
    WHEN 'RECORDATORIO_TAREA' THEN 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1'
    WHEN 'REACTIVACION_TAREA' THEN 'https://panel.alejandramunozabogada.com/tareas?tarea=1#tarea-1'
    WHEN 'REACTIVACION_EVENTO' THEN 'https://panel.alejandramunozabogada.com/procesos/1#evento-1'
    WHEN 'REACTIVACION_COMUNICACION' THEN 'https://panel.alejandramunozabogada.com/chat/1/2'
    WHEN 'ACTUACIONES_DIGEST' THEN NULL
    WHEN 'RECUPERAR_PASSWORD' THEN 'https://panel.alejandramunozabogada.com/restablecer-password?token=ejemplo'
    WHEN 'CONTRATO_FIRMADO' THEN 'https://panel.alejandramunozabogada.com/procesos/1#documentos'
    WHEN 'CHAT_MENSAJE' THEN 'https://panel.alejandramunozabogada.com/chat/1/2'
    ELSE enlace_ejemplo
END,
updated_at = NOW()
WHERE clave IN (
    'EVENTO_AGENDA', 'PROCESO_ACTUALIZACION', 'ABOGADO_CREDENCIALES',
    'CLIENTE_CREDENCIALES', 'DOCUMENTO_REVISION', 'COMUNICACION_CLIENTE_ABOGADO',
    'COMUNICACION_ABOGADO_CLIENTE', 'COLABORADOR_AGREGADO', 'ACTUACION_NOTIFICADA',
    'SOLICITUD_DOCUMENTO', 'DOCUMENTO_RECIBIDO', 'TAREA_ACCION', 'SUBTAREA_ASIGNADA',
    'RECORDATORIO_TAREA', 'REACTIVACION_TAREA', 'REACTIVACION_EVENTO',
    'REACTIVACION_COMUNICACION', 'ACTUACIONES_DIGEST', 'RECUPERAR_PASSWORD',
    'CONTRATO_FIRMADO', 'CHAT_MENSAJE'
);
